-- 199 (Pedro, 30/09/2026): a REVISÃO DAS CONVERSAS DA SEMANA aplicada.
-- "a Nay cheque conversa por conversa, define em qual estágio o corretor parou para que
--  ela continue respondendo de onde ele parou; os corretores que têm negócio e documento
--  põe a tag Tel; o resto já separa certinho". A etapa de cada um saiu de
-- nay-core/scripts/revisar_conversas.py (o modelo leu a conversa inteira).
--   * nai_retomada_resumo: onde ele parou e o próximo passo; entra no contexto do modelo
--     por 3 dias (nai_retomada_texto, dentro de nai_abrir_turno);
--   * negócio sério -> o Tel com a conversa (aparece em Tel no CRM; só sai com DEVOLVER);
--   * recebeu o checklist -> nai_fechamento (a Rayssa);
--   * o resto -> liberado para a Nay (liberado_em) e sem marca de Tel antiga
--     (menos o Tel escrevendo agora pelo celular, que vale 30 min).
BEGIN;
SET LOCAL lock_timeout = '3s';

CREATE TABLE IF NOT EXISTS nai_retomada_resumo (
  contato_id    bigint PRIMARY KEY REFERENCES nai_contato(id),
  etapa         text NOT NULL,
  resumo        text,
  proximo_passo text,
  imoveis       int[] NOT NULL DEFAULT '{}',
  criado_em     timestamptz NOT NULL DEFAULT now(),
  valido_ate    timestamptz NOT NULL DEFAULT now() + interval '3 days'
);

-- Pedro, 30/09: "cuidado para a Nay não mandar o imóvel para quem não está pedindo, ela tem
-- que respeitar o fluxo de identificação". O resumo é CONTEXTO, nunca ordem de mandar imóvel.
CREATE OR REPLACE FUNCTION nai_retomada_texto(p_contato bigint) RETURNS text LANGUAGE sql STABLE AS $$
  SELECT E'(informação de sistema) CONTEXTO DA CONVERSA ATÉ AQUI (revisão de '
         || to_char(r.criado_em AT TIME ZONE 'America/Manaus', 'DD/MM') || ', etapa ' || r.etapa || '): '
         || coalesce(r.resumo, '')
         || coalesce(E'\nSe ELE voltar a esse assunto: ' || nullif(r.proximo_passo, ''), '')
         || E'\nIsto é só para você saber onde ele parou. NÃO mande card, foto nem lista de imóvel sem ele pedir '
         || E'NESTA mensagem; se ele só cumprimentar ou agradecer, responda isso e pergunte como pode ajudar.\n'
    FROM nai_retomada_resumo r
   WHERE r.contato_id = ANY (coalesce(nai_contato_irmaos(p_contato), ARRAY[p_contato])) AND r.valido_ate > now()
   ORDER BY r.criado_em DESC LIMIT 1;
$$;

-- A PAREDE "SEM PEDIDO, SEM IMÓVEL" (71) estava morta desde 25/09: nai_jev_pedido nunca tem dado
-- e nai_pediu_imovel devolvia sempre true. Cumprimento ou agradecimento sozinhos nunca são pedido:
-- "Achar codigo na resposta" não manda card nem foto. "ok" e "sim" ficam de fora de propósito
-- (respondem "quer as fotos?").
CREATE OR REPLACE FUNCTION public.nai_pediu_imovel(p_turno bigint) RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT CASE WHEN nai_so_cumprimentou(t.texto)
                OR lower(btrim(coalesce(t.texto, ''))) ~ '^(muito )?(obrigad[oa]s?|obg|vlw|valeu|agrade[cç]o)( nay)?[\s!.,🙏👍😊]*$'
              THEN false
              ELSE coalesce(nai_jev_pedido(p_turno), true) END
    FROM nai_turno t WHERE t.id = p_turno;
$$;

-- AS VISITAS JÁ CONFIRMADAS PELO FLUXO ANTIGO passam para a Rayssa (197), com a confirmação
-- completa para ela; a que espera o "sim" do corretor (confirmando) continua com a Nay.
DO $$
DECLARE v record; v_apr bigint := nai_aprovador_contato();
BEGIN
  FOR v IN SELECT * FROM nai_visita
            WHERE estado IN ('aguardando_proprietario', 'negociando', 'aguardando_acesso', 'aguardando_motoboy',
                             'confirmada', 'com_tel')
              AND (quando IS NULL OR quando > now() - interval '2 hours') LOOP
    UPDATE nai_visita SET estado = 'com_rayssa', aguardando = 'equipe', atualizado_em = now() WHERE id = v.id;
    PERFORM nai_evento(v.id, 'com_a_rayssa', 'revisão 30/09: estava ' || v.estado);
    IF v_apr IS NOT NULL THEN
      PERFORM nai_enfileirar_texto(NULL, v.id, v_apr, 'equipe',
        nai_texto_visita_completa(v.id, nai_cfg('aprovador_visita_nome', 'Rayssa')
          || ', esta visita já estava confirmada (' || v.estado || ') e agora é sua: o corretor está na aba Visitas'),
        'visita_com_a_rayssa', 450);
    END IF;
  END LOOP;
END $$;

DO $$
DECLARE d text; de text := $a$'contexto', CASE WHEN v_papel = 'corretor' THEN nai_etapa_para_o_modelo(v_contato) || E'\n' ELSE '' END$a$;
        para text := $a$'contexto', CASE WHEN v_papel = 'corretor' THEN nai_etapa_para_o_modelo(v_contato) || E'\n' || coalesce(nai_retomada_texto(v_contato), '') ELSE '' END$a$;
        n int;
BEGIN
  d := pg_get_functiondef('public.nai_abrir_turno(text,text,text,text,bigint[])'::regprocedure);
  n := (length(d) - length(replace(d, de, ''))) / length(de);
  IF n <> 1 THEN RAISE EXCEPTION 'nai_abrir_turno: o trecho do contexto aparece % vez(es)', n; END IF;
  EXECUTE replace(d, de, para);
END $$;

