INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (10850, 'recebeu_imovel', 'Perguntou se o Living Confort fica em andar alto ou baixo. Nay enviou fotos e ofereceu agendar uma visita, mas não houve confirmação nem retorno sobre os imóveis.', 'Retome perguntando se conseguiu ver as fotos e esclareça a dúvida sobre o andar; se tiver interesse, peça um horário para a visita.', ARRAY[]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
UPDATE nai_contato SET liberado_em = coalesce(liberado_em, now()), liberado_motivo = coalesce(liberado_motivo, 'revisão 30/09: ' || 'recebeu_imovel'), humano_assumiu_em = NULL, humano_motivo = NULL WHERE id = ANY (ARRAY[10850]::bigint[]) AND NOT (humano_motivo = 'o Tel escreveu pelo celular' AND humano_assumiu_em > now() - interval '30 minutes');

