INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (10399, 'recebeu_imovel', 'O corretor busca opções para clientes, sobretudo compra de até R$ 500 mil, com 2 ou 3 quartos e semi-mobiliado. Recebeu opções; por último avaliou o Smile Village Cidade Nova, perguntou o andar e a comissão. O imóvel fica no 4º andar.', 'Retome o Smile Village Cidade Nova (cód. 5754), confirme se o cliente tem interesse e se deseja avançar ou visitar; ofereça opções de compra no Smile Flores se necessário.', ARRAY[5764,2120,5743,5614,4390,5725,5754]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
