INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (5781, 'recebeu_imovel', 'Busca apartamento para locação na região da Ponta Negra, até R$ 3,5 mil, climatizado, com modulados e preferencialmente duas vagas cobertas. Recebeu fotos e informações de opções; perguntou a localização de uma e informou que o imóvel 5734 já foi alugado.', 'Retome a busca com os filtros informados e envie opções disponíveis na região da Ponta Negra, confirmando localização, climatização, modulados e vagas.', ARRAY[5734]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
