INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (10643, 'documentacao', 'Corretor busca locação para três pessoas. A visita à casa aconteceu; enviou documentos de Bruno e David e informou que a terceira moradora é amiga deles. A análise de Bruno foi aprovada no Serasa, mas ainda falta comprovar renda suficiente.', 'Retome a análise da documentação: confirme a relação entre os moradores e solicite a comprovação de renda que falta. Informe o resultado da aprovação e, se estiverem aptos, oriente os próximos passos para fechar a locação.', ARRAY[5749]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
