INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (11452, 'negociacao', 'Foi apresentada proposta de R$ 253.000, com comissão de 5% e transferência após quitação integral. Nay enviou opções, inclusive o imóvel 5754; o corretor informou que o cliente ainda não deu retorno.', 'Perguntar se o cliente respondeu à proposta de R$ 253.000 e, conforme o retorno, alinhar as condições e encaminhar a negociação.', ARRAY[5754,5744,3463,5741,5696,2228]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
