INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (10926, 'quase_visita', 'Buscou apartamento mobiliado para temporada, até R$ 3 mil, de preferência na Torquato, e também casa à venda por até R$ 400 mil à vista. Depois houve coordenação para visitar Solar da Praia/Castelli, mas a visita não consta como confirmada.', 'Pergunte se conseguiram visitar o Solar da Praia e qual foi o retorno. Se não visitaram, alinhe um horário; retome também a busca da casa, se ainda estiver em aberto.', ARRAY[]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
