-- EDMAR (…9102): documentacao | TEL
INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (10549, 'documentacao', 'Edmar levou uma cliente para visitar uma casa; a visita foi confirmada e avançaram para documentação, aprovação e contrato. Agora informou que surgiu uma restrição cadastral que o cliente pretende quitar.', 'Perguntar se a restrição foi paga e acompanhar a atualização da análise de crédito e o envio dos documentos para dar sequência ao contrato.', ARRAY[4778]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
