INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (10196, 'negociacao', 'Cliente interessada na casa do Parque 10, com visita combinada para quarta às 15h. O corretor perguntou se a locadora permite adaptar os quartos para atendimento infantil e disse que quer fechar.', 'Retome a autorização da locadora para a adaptação e esclareça com o corretor quais são os próximos passos para fechar.', ARRAY[]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
