-- Fabiane (…9292): recebeu_imovel
INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (12681, 'recebeu_imovel', 'Busca casa para compra para uma cliente, com limite informado de R$ 900 mil e preferência por Ponta Negra; depois mencionou Campo Grande. Recebeu opções e fotos, perguntou sobre fachada, negociação e financiamento, mas não escolheu imóvel nem marcou visita.', 'Retome perguntando se a cliente gostou de alguma opção e confirme região e limite de orçamento. Se houver interesse, esclareça disponibilidade e consulte o proprietário sobre negociação e financiamento.', ARRAY[3210,3611,4870,5265,5585,5605,4993,2193,3612,4904]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
