-- Magna (…7873): negociacao | TEL
INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (12383, 'negociacao', 'Magna busca locações para clientes e recebeu opções. Perguntou sobre caução e despesas do imóvel 5743, sem resposta. Depois mencionou clientes na Barreira e na Djalma e disse que vai filtrar as opções.', 'Retomar as dúvidas pendentes sobre caução e despesas do 5743; depois perguntar quais bairros e características os clientes aceitam na Barreira ou na Djalma.', ARRAY[1595,5733,5724,5726,4904,5743]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
UPDATE nai_contato SET humano_assumiu_em = now(), humano_motivo = 'revisão 30/09: A corretora perguntou se a caução do imóvel 5743 pode ser parcelada em 2 vezes e quais despesas ficam por conta do inquilino; essas condições ainda não foram respondidas.' WHERE id = 12383 AND NOT EXISTS (SELECT 1 FROM nai_visita v WHERE v.corretor_id = ANY (ARRAY[12383,12493]::bigint[]) AND nai_visita_com_a_rayssa(v.estado, v.quando));

