INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (9165, 'visita_confirmada', 'A visita à casa foi alinhada para 29/09. Houve divergência entre 13h30 e 14h; o cliente chegou atrasado e estava procurando onde estacionar, sem confirmação de que a visita terminou.', 'Perguntar se a visita aconteceu e como foi; registrar o retorno do corretor e oferecer próximos passos conforme o interesse do cliente.', ARRAY[]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
