INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (10524, 'quase_visita', 'Tem cliente interessado na casa 840, no Dom Pedro. A visita foi remarcada algumas vezes; a proprietária só pode sábado às 13h. A corretora ficou de informar a cliente, e a visita de 03/10 consta como aguardando confirmação.', 'Pergunte se a cliente confirmou a visita de sábado, 03/10, às 13h. Se sim, confirme os detalhes; se não, verifique novo horário com a proprietária.', ARRAY[840]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
