INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (9240, 'quase_visita', 'A corretora busca locação; recebeu fotos e informações do Acquarelle (2943). A visita ao Amazonas Flat (5737) foi cancelada antes e agora ela consulta a cliente para agendar. Ainda não há visita confirmada.', 'Pergunte se a cliente decidiu visitar o Amazonas Flat (5737) e, se sim, combine dia e horário. Confirme a disponibilidade antes de agendar.', ARRAY[5737,2943,4904]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
