INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (11576, 'recebeu_imovel', 'Corretor buscou aluguel até R$ 3 mil em Dom Pedro ou regiões próximas. Recebeu opções na Ponta Negra e disse que as enviaria ao cliente; não há retorno sobre a avaliação.', 'Perguntar se o cliente avaliou as opções e qual imóvel interessou; se houver interesse, verificar disponibilidade e ajudar a agendar uma visita.', ARRAY[5733,5722,5727,5724]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
