INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (10359, 'recebeu_imovel', 'Corretor busca apartamento de 2 quartos no Leve Castanheiras, priorizando o menor preço. Escolheu avaliar o código 5346, de R$ 230 mil, perguntou andar e itens que ficam; foi informado que é no 1º andar e ficará com modulados e ar. Nay perguntou se o cliente quer visitar.', 'Retome perguntando se o cliente quer visitar o 5346; se não, ofereça opções mais baratas e confirme o limite de preço.', ARRAY[4262,5346]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
