-- Solange (…3869): documentacao | TEL
INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (4906, 'documentacao', 'A corretora agendou visita à casa mobiliada no Aleixo; após a visita, informou que o cliente fecharia. Enviou documentos e comprovantes, mas a renda individual não basta e surgiu a questão de incluir a corretora no contrato.', 'Retomar a análise da locação: esclarecer quem será incluído no contrato e solicitar os extratos de pessoa física e demais documentos necessários para comprovar a renda dos participantes.', ARRAY[5613,5752,2120]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
UPDATE nai_contato SET humano_assumiu_em = now(), humano_motivo = 'revisão 30/09: Locação em fase de fechamento e análise documental; há dúvida sobre colocar o contrato no nome da corretora e sobre comprovação de renda dos envolvidos.' WHERE id = 4906 AND NOT EXISTS (SELECT 1 FROM nai_visita v WHERE v.corretor_id = ANY (ARRAY[4906,4908]::bigint[]) AND nai_visita_com_a_rayssa(v.estado, v.quando));

-- Luiz (…3264): negociacao | TEL
INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (11246, 'negociacao', 'O corretor está avaliando um imóvel e respondeu sobre a vista/localização. A conversa chegou à negociação: possibilidade de R$ 290 mil à vista, sem reduzir o valor a ponto de comprometer a comissão.', 'Retome a negociação, confirme se o corretor aceita R$ 290 mil à vista e alinhe o valor e a comissão antes de avançar.', ARRAY[]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
