INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (10929, 'negociacao', 'Buscou casas para locação no Nova Cidade, mas não havia opção disponível. Também avaliou imóveis e perguntou sobre as fotos do 5753; agora quer saber se o proprietário aceita parcelar a venda em 10 vezes.', 'Confirmar com o proprietário se aceita parcelar o imóvel 5753 em 10 vezes e retornar ao corretor. Depois, esclarecer se ele ainda precisa de opções de locação no Nova Cidade.', ARRAY[4262,5753]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
