INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (4914, 'quase_visita', 'Busca casas para clientes até R$ 700 mil, preferencialmente em Campos Elíseos, Planalto, Belvedere ou Parque 10, em ruas tranquilas. Recebeu opções; Nay pediu para remarcar a visita à casa da Ponta Negra, ainda sem confirmação.', 'Retome a visita à casa da Ponta Negra: confirme a disponibilidade da cliente e proponha datas. Pergunte também se alguma das casas enviadas atendeu aos clientes.', ARRAY[5706,5613,3166,5647]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
