INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (12278, 'quase_visita', 'Busca imóvel para alugar até R$ 2.500. Recebeu informações e fotos do Amazonas Flat, código 5737, e tem cliente interessada em visitar, mas dia e horário ainda não foram confirmados. A cliente será informada sobre as condições de caução.', 'Confirmar com o proprietário se aceita visita após as 19h e retornar ao corretor. Verificar também se a cliente aceita as condições de locação e combinar a visita.', ARRAY[5737]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
UPDATE nai_contato SET humano_assumiu_em = now(), humano_motivo = 'revisão 30/09: A visita à noite, a partir das 19h, depende de confirmação do proprietário; também há uma condição de locação (dois cauções e aluguel antecipado) que pode afetar o interesse da cliente.' WHERE id = 12278 AND NOT EXISTS (SELECT 1 FROM nai_visita v WHERE v.corretor_id = ANY (ARRAY[12278,12283]::bigint[]) AND nai_visita_com_a_rayssa(v.estado, v.quando));

