INSERT INTO nai_retomada_resumo (contato_id, etapa, resumo, proximo_passo, imoveis) VALUES (11431, 'buscando_imovel', 'Busca imóvel para a cliente; pediu fotos e descrição do Coral, mas foi informado que já alugou. Nay perguntou se serve uma opção mobiliada de R$ 10 mil no Sollar da Villa, sem resposta ainda.', 'Perguntar se a opção mobiliada de R$ 10 mil no Sollar da Villa atende à cliente; se sim, enviar fotos e descrição. Se não, levantar os critérios para buscar alternativas.', ARRAY[]::int[]) ON CONFLICT (contato_id) DO UPDATE SET etapa = EXCLUDED.etapa, resumo = EXCLUDED.resumo, proximo_passo = EXCLUDED.proximo_passo, imoveis = EXCLUDED.imoveis, criado_em = now(), valido_ate = now() + interval '3 days';
UPDATE nai_contato SET liberado_em = coalesce(liberado_em, now()), liberado_motivo = coalesce(liberado_motivo, 'revisão 30/09: ' || 'buscando_imovel'), humano_assumiu_em = NULL, humano_motivo = NULL WHERE id = ANY (ARRAY[11431,11442]::bigint[]) AND NOT (humano_motivo = 'o Tel escreveu pelo celular' AND humano_assumiu_em > now() - interval '30 minutes');

COMMIT;
